231	    /**
232	     * Return the Pet with the given name, or null if none found for this Owner.
233	     *
234	     * @param name to test
235	     * @return true if pet name is already in use
236	     */
237	    public Pet getPet(String name, boolean ignoreNew) {
238	        name = name.toLowerCase();
239	        for (Pet pet : getPetsInternal()) {
240	            if (!ignoreNew || !pet.isNew()) {
241	                String compName = pet.getName();
242	                compName = compName.toLowerCase();
243	                if (compName.equals(name)) {
244	                    return pet;
