237	    /**
238	     * Convert a raw telephone input to its E.164 representation, or {@code null} if it
239	     * cannot form a valid E.164 number.
240	     *
241	     * <p>A leading '+' and country code are kept when present; otherwise country code
242	     * '+61' is assumed and a single leading '0' is dropped from the national digits.
243	     * Spaces, dashes and brackets (indeed any non-digit) are stripped. The result must
244	     * carry 8 to 15 digits after the '+'.
245	     */
246	    private String toE164(String telephone) {
247	        if (telephone == null) {
248	            return null;
249	        }
250	        boolean hasCountryCode = telephone.trim().startsWith("+");
251	        String digits = telephone.replaceAll("\\D", "");
252	        String e164;
253	        if (hasCountryCode) {
254	            e164 = digits;
255	        } else {
256	            if (digits.startsWith("0")) {
257	                digits = digits.substring(1);
258	            }
259	            e164 = "61" + digits;
260	        }
261	        if (e164.length() < 8 || e164.length() > 15) {
262	            return null;
263	        }
264	        return "+" + e164;
265	    }
