267	    /**
268	     * Whether any existing owner already holds the given telephone number. Both the
269	     * candidate and each stored number are compared in E.164 form, so the check does not
270	     * depend on how each was originally formatted.
271	     */
272	    private boolean isTelephoneInUse(String telephone) {
273	        return this.clinicService.findAllOwners().stream()
274	            .map(Owner::getTelephone)
275	            .filter(Objects::nonNull)
276	            .map(this::toE164)
277	            .filter(Objects::nonNull)
278	            .anyMatch(telephone::equals);
279	    }
