281	    /**
282	     * Whether any existing owner already shares a household with the candidate, i.e. has both
283	     * the same lastName and the same address. Both fields are compared case-insensitively and
284	     * with internal runs of whitespace collapsed to a single space (and surrounding whitespace
285	     * trimmed), so the check does not depend on casing or spacing.
286	     */
287	    private boolean isHouseholdInUse(String lastName, String address) {
288	        String candidateLastName = normalizeName(lastName);
289	        String candidateAddress = addressNormalizer.normalize(address);
290	        return this.clinicService.findAllOwners().stream()
291	            .anyMatch(existing -> normalizeName(existing.getLastName()).equals(candidateLastName)
292	                && addressNormalizer.normalize(existing.getAddress()).equals(candidateAddress));
293	    }
