295	    /**
296	     * Normalize an owner's name for household comparison: trim, collapse internal whitespace runs
297	     * to a single space and lower-case. A null value normalizes to the empty string.
298	     */
299	    private String normalizeName(String value) {
300	        if (value == null) {
301	            return "";
302	        }
303	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
304	    }
