52	
53	import jakarta.transaction.Transactional;
54	
55	/**
56	 * @author Vitaliy Fedoriv
57	 */
58	
59	@RestController
60	@CrossOrigin(exposedHeaders = "errors, content-type")
61	@RequestMapping("/api")
62	public class OwnerRestControllerV1 implements OwnersApi {
63	
64	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
65	
66	    private final ClinicService clinicService;
67	
68	    private final OwnerMapper ownerMapper;
69	
70	    private final PetMapper petMapper;
71	
72	    private final VisitMapper visitMapper;
73	
74	    private final AddressNormalizer addressNormalizer;
75	
76	    public OwnerRestControllerV1(ClinicService clinicService,
77	                                 OwnerMapper ownerMapper,
78	                                 PetMapper petMapper,
79	                                 VisitMapper visitMapper,
80	                                 AddressNormalizer addressNormalizer) {
81	        this.clinicService = clinicService;
82	        this.ownerMapper = ownerMapper;
83	        this.petMapper = petMapper;
84	        this.visitMapper = visitMapper;
85	        this.addressNormalizer = addressNormalizer;
86	    }
87	
88	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
89	    @Override
90	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
91	        Collection<Owner> owners;
92	        if (lastName != null) {
93	            owners = this.clinicService.findOwnerByLastName(lastName);
94	        } else {
95	            owners = this.clinicService.findAllOwners();
96	        }
97	        if (owners.isEmpty()) {
98	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
99	        }
100	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
101	    }
102	
103	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
104	    @Override
105	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
106	        Owner owner = this.clinicService.findOwnerById(ownerId);
107	        if (owner == null) {
108	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
109	        }
110	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
111	    }
112	
113	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
114	    @Override
115	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
116	        HttpHeaders headers = new HttpHeaders();
117	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
118	        String address = addressNormalizer.normalize(owner.getAddress());
119	        if (address.isEmpty()) {
120	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
121	        }
122	        owner.setAddress(address);
123	        String telephone = toE164(owner.getTelephone());
124	        if (telephone == null) {
125	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
126	        }
127	        owner.setTelephone(telephone);
128	        LocalDate effectiveDate = owner.getRegistrationDate() != null
129	            ? owner.getRegistrationDate() : LocalDate.now();
130	        owner.setRegistrationDate(toBusinessDay(effectiveDate));
131	        if (isDailyLimitReached(owner.getRegistrationDate())) {
132	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
133	        }
134	        if (isTelephoneInUse(telephone)) {
135	            return new ResponseEntity<>(HttpStatus.CONFLICT);
136	        }
137	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
138	        if (!sharesHousehold && isHouseholdInUse(owner.getLastName(), owner.getAddress())) {
139	            return new ResponseEntity<>(HttpStatus.CONFLICT);
140	        }
141	        if (sharesHousehold) {
142	            owner.setHouseholdId(householdId(owner.getLastName(), owner.getAddress()));
143	        }
144	        if (isCityAtCapacity(owner.getCity())) {
145	            return new ResponseEntity<>(HttpStatus.CONFLICT);
146	        }
147	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
148	        owner.setNamesakeCount(namesakeCount(owner.getFirstName(), owner.getLastName()));
149	        owner.setBulkSignupWarning(isBulkSignup(owner.getRegistrationDate()));
150	        this.clinicService.saveOwner(owner);
151	        AUDIT.info("owner created id={} customerCode={} registrationDate={}",
152	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate());
153	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
154	        headers.setLocation(UriComponentsBuilder.newInstance()
155	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
156	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
157	    }
158	
159	    /**
160	     * Build the customer code for a newly created owner, formatted {@code '<CITY3>-<LAST3>-<NNNN>'}
161	     * where CITY3 is the upper-cased first three letters of {@code city}, LAST3 the upper-cased first
162	     * three letters of {@code lastName} and NNNN a per-city 4-digit zero-padded sequence equal to one
163	     * more than the number of owners already in that city (e.g. {@code 'LON-SMI-0007'}).
164	     */
165	    private String nextCustomerCode(String city, String lastName) {
166	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase();
167	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
168	        int sequence = (int) this.clinicService.findAllOwners().stream()
169	            .filter(existing -> existing.getCity() != null && existing.getCity().equalsIgnoreCase(city))
170	            .count() + 1;
171	        return String.format("%s-%s-%04d", city3, last3, sequence);
172	    }
173	
174	    /**
175	     * Whether the per-day owner creation limit has been reached for the given business day, i.e.
176	     * 100 or more owners already carry that {@code registrationDate}. The day is the adjusted
177	     * (business-day) registration date of the owner being created, so owners are counted per
178	     * business day. When true, a new owner must be rejected with {@code 429 Too Many Requests}.
179	     */
180	    private boolean isDailyLimitReached(LocalDate day) {
181	        long count = this.clinicService.findAllOwners().stream()
182	            .filter(existing -> day.equals(existing.getRegistrationDate()))
183	            .count();
184	        return count >= 100;
185	    }
186	
187	    /**
188	     * Whether creating this owner pushes the day's total past the bulk-signup threshold, i.e.
189	     * more than 80 owners have already been created for the given business day. Counts the owners
190	     * already carrying that {@code registrationDate} (the same accumulation as the daily-limit
191	     * rule); when that count exceeds 80 the newly created owner is flagged with a bulk-signup
192	     * warning.
193	     */
194	    private boolean isBulkSignup(LocalDate day) {
195	        long count = this.clinicService.findAllOwners().stream()
196	            .filter(existing -> day.equals(existing.getRegistrationDate()))
197	            .count();
198	        return count > 80;
199	    }
200	
201	    /**
202	     * Roll a registration date forward onto a business day: when it falls on a Saturday or Sunday,
203	     * advance it to the following Monday; a weekday is returned unchanged.
204	     */
205	    private LocalDate toBusinessDay(LocalDate date) {
206	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY || date.getDayOfWeek() == DayOfWeek.SUNDAY) {
207	            date = date.plusDays(1);
208	        }
209	        return date;
210	    }
211	
212	    /**
213	     * Whether the given city has reached its owner capacity, i.e. it already contains 50 or
214	     * more owners. Cities are compared case-insensitively, matching {@link #nextCustomerCode}.
215	     */
216	    private boolean isCityAtCapacity(String city) {
217	        long count = this.clinicService.findAllOwners().stream()
218	            .filter(existing -> existing.getCity() != null && existing.getCity().equalsIgnoreCase(city))
219	            .count();
220	        return count >= 50;
221	    }
222	
223	    /**
224	     * The number of existing owners that already share the given firstName and lastName,
225	     * compared case-insensitively (and with surrounding whitespace trimmed and internal
226	     * whitespace runs collapsed). Counted over the owners present before this create.
227	     */
228	    private int namesakeCount(String firstName, String lastName) {
229	        String candidateFirstName = normalizeName(firstName);
230	        String candidateLastName = normalizeName(lastName);
231	        return (int) this.clinicService.findAllOwners().stream()
232	            .filter(existing -> normalizeName(existing.getFirstName()).equals(candidateFirstName)
233	                && normalizeName(existing.getLastName()).equals(candidateLastName))
234	            .count();
235	    }
236	
237	    /**
238	     * Convert a raw telephone input to its E.164 representation, or {@code null} if it
239	     * cannot form a valid E.164 number.
240	     *
241	     * <p>A leading '+' and country code are kept when present; otherwise country code
242	     * '+61' is assumed and a single leading '0' is dropped from the national digits.
243	     * Spaces, dashes and brackets (indeed any non-digit) are stripped. The result must
244	     * carry 8 to 15 digits after the '+'.
245	     */
246	    private String toE164(String telephone) {
247	        if (telephone == null) {
248	            return null;
249	        }
250	        boolean hasCountryCode = telephone.trim().startsWith("+");
251	        String digits = telephone.replaceAll("\\D", "");
252	        String e164;
253	        if (hasCountryCode) {
254	            e164 = digits;
255	        } else {
256	            if (digits.startsWith("0")) {
257	                digits = digits.substring(1);
258	            }
259	            e164 = "61" + digits;
260	        }
261	        if (e164.length() < 8 || e164.length() > 15) {
262	            return null;
263	        }
264	        return "+" + e164;
265	    }
266	
267	    /**
268	     * Whether any existing owner already holds the given telephone number. Both the
269	     * candidate and each stored number are compared in E.164 form, so the check does not
270	     * depend on how each was originally formatted.
271	     */
272	    private boolean isTelephoneInUse(String telephone) {
273	        return this.clinicService.findAllOwners().stream()
274	            .map(Owner::getTelephone)
275	            .filter(Objects::nonNull)
276	            .map(this::toE164)
277	            .filter(Objects::nonNull)
278	            .anyMatch(telephone::equals);
279	    }
280	
281	    /**
282	     * Whether any existing owner already shares a household with the candidate, i.e. has both
283	     * the same lastName and the same address. Both fields are compared case-insensitively and
284	     * with internal runs of whitespace collapsed to a single space (and surrounding whitespace
285	     * trimmed), so the check does not depend on casing or spacing.
286	     */
287	    private boolean isHouseholdInUse(String lastName, String address) {
288	        String candidateLastName = normalizeName(lastName);
289	        String candidateAddress = addressNormalizer.normalize(address);
290	        return this.clinicService.findAllOwners().stream()
291	            .anyMatch(existing -> normalizeName(existing.getLastName()).equals(candidateLastName)
292	                && addressNormalizer.normalize(existing.getAddress()).equals(candidateAddress));
293	    }
294	
295	    /**
296	     * Normalize an owner's name for household comparison: trim, collapse internal whitespace runs
297	     * to a single space and lower-case. A null value normalizes to the empty string.
298	     */
299	    private String normalizeName(String value) {
300	        if (value == null) {
301	            return "";
302	        }
303	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
304	    }
305	
306	    /**
307	     * A stable shared identifier for the household formed by a given lastName and address.
308	     * Derived deterministically from the normalized (case-insensitive, whitespace-collapsed)
309	     * lastName and address, so every owner sharing the same household is assigned the same
310	     * value regardless of the order in which they are created. Formatted as the first 12
311	     * upper-case hex characters of the SHA-256 of {@code '<lastName>|<address>'}.
312	     */
313	    private String householdId(String lastName, String address) {
314	        String key = normalizeName(lastName) + "|" + addressNormalizer.normalize(address);
315	        try {
316	            byte[] digest = MessageDigest.getInstance("SHA-256")
317	                .digest(key.getBytes(StandardCharsets.UTF_8));
318	            StringBuilder sb = new StringBuilder(digest.length * 2);
319	            for (byte b : digest) {
320	                sb.append(String.format("%02x", b));
321	            }
322	            return sb.substring(0, 12).toUpperCase();
323	        }
324	        catch (NoSuchAlgorithmException e) {
325	            throw new IllegalStateException("SHA-256 not available", e);
326	        }
327	    }
328	
329	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
330	    @Override
